editorial:
While searching for the minimum, compare the midpoint with the right endpoint. If the midpoint is larger, the pivot lies strictly to its right. Otherwise the pivot is at or left of the midpoint. The virtual array a[(pivot+i)%n] is increasing, so search it and translate the index back. Time O((q+1) log n) after reading, space O(n).
~~~
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n,q; cin>>n>>q;
    vector<int>a(n);
    for (auto& x:a) cin>>x;
    int l=0,r=n-1;
    while (l<r) {
        int m=l+(r-l)/2;
        if (a[m]>a[r]) l=m+1;
        else r=m;
    }
    int pivot=l;
    while (q--) {
        int x; cin>>x;
        l=0; r=n;
        while (l<r) {
            int m=l+(r-l)/2;
            if (a[(pivot+m)%n]<x) l=m+1;
            else r=m;
        }
        int at=(pivot+l)%n;
        cout<<(l<n && a[at]==x?at+1:0)<<'\n';
    }
}
